import{_ as i,l as o,o as e,c as n,v as t,p as s,x as r,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"RAG 对微调","description":"","frontmatter":{"title":"RAG 对微调","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-vs-finetune.md","filePath":"llm/rag-vs-finetune.md","lastUpdated":1789023840000}'),A={name:"llm/rag-vs-finetune.md"};function h(_,a,c,m,u,B){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="rag-对微调" tabindex="-1">RAG 对微调 <a class="header-anchor" href="#rag-对微调" aria-label="Permalink to &quot;RAG 对微调&quot;">​</a></h1><div class="epigraph"><p>私有知识要更新、要可引用、要能撤销，放索引。格式、语气、任务程序放权重。用微调背手册，过时与幻觉会绑在参数里。</p><footer>—— Ovadia 等对微调与检索的比较；Lewis 等 RAG 的非参数记忆</footer></div><p><a href="/llm/pq-vector-index">上一课</a>用子空间码本换内存，查询侧保持浮点，最终短列表用精确重排。索引已经能省；还要决定知识写在哪。缺口是 RAG 对微调的决策边界——避免「再训一遍就不用检索」。本课写这一边界，不重推 PQ 的码本。后课投毒防御默认：索引可被攻击，不等于该把知识熔进权重。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>微调能抬领域术语与答题格式，对<strong>封闭、稳定、不许外泄到提示</strong>的程序有效。对日期、价格、条款、内部工单，微调刚结束就过时，且无法逐条引用、无法按权限过滤。检索相反：更新是写文档，引用是块 ID，权限是元数据。代价是管道复杂、延迟、以及本单元写过的忠实度问题。</p><p>混合是常态：轻量 SFT 教会「如何用检索到的块作答」，知识仍在索引。用 SFT 把手册抄进权重，再加 RAG，会让参数与块冲突，归因更难。</p><p><span class="marginnote">长上下文窗口变大，不自动取消这道题。窗口是容量，索引是可更新集合与权限边界。见长上下文对 RAG 课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>决策表：变更频率高 → 索引；需引用与权限 → 索引；任务格式与工具规程稳定 → SFT / 指令。评测用时间切片：新文档进索引后未经微调是否立刻可答；过时文档删除后是否立刻不再被当事实。微调组应在同一切片上失败，才说明职责分对。</p>',9)),(e(),s(p,null,{default:r(()=>[E(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20KNOW%5B%22%E7%9F%A5%E8%AF%86%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20IDX%5B%22%E5%8F%AF%E6%9B%B4%E6%96%B0%20%2F%20%E8%A6%81%E5%BC%95%E7%94%A8%20%E2%86%92%20%E7%B4%A2%E5%BC%95%22%5D%0A%20%20KNOW%20--%3E%20WT%5B%22%E7%A8%B3%E5%AE%9A%E7%A8%8B%E5%BA%8F%20%2F%20%E6%A0%BC%E5%BC%8F%20%E2%86%92%20%E6%9D%83%E9%87%8D%22%5D%0A%20%20IDX%20--%3E%20PIPE%5B%22RAG%20%E7%AE%A1%E9%81%93%22%5D%0A%20%20WT%20--%3E%20SFT%5B%22SFT%20%E6%95%99%E5%A6%82%E4%BD%95%E7%94%A8%E5%9D%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>参数记忆是压缩过的统计，单条事实没有地址。非参数记忆有地址，才能撤销与审计。微调把新事实写入权重的同时，也扰动无关能力（灾难遗忘）。检索不扰动权重，但扰动上下文条件。冲突时阅读器需要明确指令「以块为准」，否则统计先验会赢。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>极小语料、极强保密、禁止任何文档出域时，可能只能微调且不上检索——那是约束，不是精度更优。下一课：索引可写意味着对手也可写，需要投毒防御。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可更新、可引用、要权限的知识放索引；稳定程序放权重。</li><li>SFT 应教「如何用块」，而不是把手册背进参数。</li><li>用时间切片验收更新与撤销。</li><li>出处：Ovadia 等微调对检索；Lewis 等 RAG。</li></ul>',6))])}const D=i(A,[["render",h]]);export{T as __pageData,D as default};
